OnDatagramReceived(datagram):
  // このデータグラムによってサーバーのブロックが解除される場合は、
  // デッドロックを避けるためにPTOタイマーを設定します。
  if (server was at anti-amplification limit):
    SetLossDetectionTimer()
    if loss_detection_timer.timeout < now():
      // 増幅制限が適用されている間にPTOが期限切れになって
      // いたはずであれば、PTOを実行します。
      OnLossDetectionTimeout()

IncludesAckEliciting(packets):
  for packet in packets:
    if (packet.ack_eliciting):
      return true
  return false

OnAckReceived(ack, pn_space):
  if (largest_acked_packet[pn_space] == infinite):
    largest_acked_packet[pn_space] = ack.largest_acked
  else:
    largest_acked_packet[pn_space] =
        max(largest_acked_packet[pn_space], ack.largest_acked)

  // DetectAndRemoveAckedPacketsは、新たに確認応答されたパケットを
  // 見つけ、それらをsent_packetsから削除します。
  newly_acked_packets =
      DetectAndRemoveAckedPackets(ack, pn_space)
  // 新たに確認応答されたパケットがなければ、何もしません。
  if (newly_acked_packets.empty()):
    return

  // 確認応答された最大のパケットが新たに確認応答され、かつ少なくとも
  // 1つの確認応答誘発パケットが新たに確認応答された場合、RTTを更新します。
  if (newly_acked_packets.largest().packet_number ==
          ack.largest_acked &&
      IncludesAckEliciting(newly_acked_packets)):
    latest_rtt =
      now() - newly_acked_packets.largest().time_sent
    UpdateRtt(ack.ack_delay)

  // ECN情報があれば処理します。
  if (ACK frame contains ECN information):
      ProcessECN(ack, pn_space)

  lost_packets = DetectAndRemoveLostPackets(pn_space)
  if (!lost_packets.empty()):
    OnPacketsLost(lost_packets)
  OnPacketsAcked(newly_acked_packets)

  // サーバーがクライアントのアドレスを検証したかどうかを
  // クライアントが確信できない場合を除き、pto_countをリセットします。
  if (PeerCompletedAddressValidation()):
    pto_count = 0
  SetLossDetectionTimer()


UpdateRtt(ack_delay):
  if (first_rtt_sample == 0):
    min_rtt = latest_rtt
    smoothed_rtt = latest_rtt
    rttvar = latest_rtt / 2
    first_rtt_sample = now()
    return

  // min_rttは確認応答遅延を無視します。
  min_rtt = min(min_rtt, latest_rtt)
  // ハンドシェイクの確認後は、ack_delayを
  // max_ack_delayで制限します。
  if (handshake confirmed):
    ack_delay = min(ack_delay, max_ack_delay)

  // 妥当であれば確認応答遅延を考慮して調整します。
  adjusted_rtt = latest_rtt
  if (latest_rtt >= min_rtt + ack_delay):
    adjusted_rtt = latest_rtt - ack_delay

  rttvar = 3/4 * rttvar + 1/4 * abs(smoothed_rtt - adjusted_rtt)
  smoothed_rtt = 7/8 * smoothed_rtt + 1/8 * adjusted_rtt

GetLossTimeAndSpace():
  time = loss_time[Initial]
  space = Initial
  for pn_space in [ Handshake, ApplicationData ]:
    if (time == 0 || loss_time[pn_space] < time):
      time = loss_time[pn_space];
      space = pn_space
  return time, space

GetPtoTimeAndSpace():
  duration = (smoothed_rtt + max(4 * rttvar, kGranularity))
      * (2 ^ pto_count)
  // デッドロック防止のPTOは現在時刻から開始します
  if (no ack-eliciting packets in flight):
    assert(!PeerCompletedAddressValidation())
    if (has handshake keys):
      return (now() + duration), Handshake
    else:
      return (now() + duration), Initial
  pto_timeout = infinite
  pto_space = Initial
  for space in [ Initial, Handshake, ApplicationData ]:
    if (no ack-eliciting packets in flight in space):
        continue;
    if (space == ApplicationData):
      // ハンドシェイクの確認まではApplication Dataを飛ばします。
      if (handshake is not confirmed):
        return pto_timeout, pto_space
      // Application Dataについてはmax_ack_delayとバックオフを含めます。
      duration += max_ack_delay * (2 ^ pto_count)

    t = time_of_last_ack_eliciting_packet[space] + duration
    if (t < pto_timeout):
      pto_timeout = t
      pto_space = space
  return pto_timeout, pto_space

PeerCompletedAddressValidation():
  // クライアントはサーバーのアドレスを暗黙的に検証するとみなします。
  if (endpoint is server):
    return true
  // サーバーは、保護されたパケットを受信したときに
  // アドレス検証を完了します。
  return has received Handshake ACK ||
       handshake confirmed

SetLossDetectionTimer():
  earliest_loss_time, _ = GetLossTimeAndSpace()
  if (earliest_loss_time != 0):
    // 時間しきい値による損失検出。
    loss_detection_timer.update(earliest_loss_time)
    return

  if (server is at anti-amplification limit):
    // 何も送信できない場合、サーバーのタイマーは設定しません。
    loss_detection_timer.cancel()
    return

  if (no ack-eliciting packets in flight &&
      PeerCompletedAddressValidation()):
    // 損失を検出する対象がないため、タイマーは設定しません。
    // ただし、サーバーが増幅防止制限によってブロックされている
    // 可能性がある場合、クライアントはタイマーを設定する必要があります。
    loss_detection_timer.cancel()
    return

  timeout, _ = GetPtoTimeAndSpace()
  loss_detection_timer.update(timeout)

OnLossDetectionTimeout():
  earliest_loss_time, pn_space = GetLossTimeAndSpace()
  if (earliest_loss_time != 0):
    // 時間しきい値による損失検出
    lost_packets = DetectAndRemoveLostPackets(pn_space)
    assert(!lost_packets.empty())
    OnPacketsLost(lost_packets)
    SetLossDetectionTimer()
    return

  if (no ack-eliciting packets in flight):
    assert(!PeerCompletedAddressValidation())
    // クライアントはデッドロック防止のパケットを送信します。Initialは
    // 増幅防止のクレジットをより多く得るためにパディングされ、
    // Handshakeパケットはアドレスの所有を証明します。
    if (has Handshake keys):
      SendOneAckElicitingHandshakePacket()
    else:
      SendOneAckElicitingPaddedInitialPacket()
  else:
    // PTO。新しいデータがあれば送信し、なければ古いデータを再送します。
    // どちらもなければ、PINGフレームを1つ送信します。
    _, pn_space = GetPtoTimeAndSpace()
    SendOneOrTwoAckElicitingPackets(pn_space)

  pto_count++
  SetLossDetectionTimer()

DetectAndRemoveLostPackets(pn_space):
  assert(largest_acked_packet[pn_space] != infinite)
  loss_time[pn_space] = 0
  lost_packets = []
  loss_delay = kTimeThreshold * max(latest_rtt, smoothed_rtt)

  // パケットを失われたとみなすまでの最小時間はkGranularityです。
  loss_delay = max(loss_delay, kGranularity)

  // この時刻より前に送信されたパケットは失われたとみなします。
  lost_send_time = now() - loss_delay

  foreach unacked in sent_packets[pn_space]:
    if (unacked.packet_number > largest_acked_packet[pn_space]):
      continue

    // パケットを損失としてマークするか、マークすべき時刻を設定します。
    // 注：ここでのkPacketThresholdの使用は、パケット番号空間に
    // 送信者が意図的に作った欠番がなかったことを前提としています。
    if (unacked.time_sent <= lost_send_time ||
        largest_acked_packet[pn_space] >=
          unacked.packet_number + kPacketThreshold):
      sent_packets[pn_space].remove(unacked.packet_number)
      lost_packets.insert(unacked)
    else:
      if (loss_time[pn_space] == 0):
        loss_time[pn_space] = unacked.time_sent + loss_delay
      else:
        loss_time[pn_space] = min(loss_time[pn_space],
                                  unacked.time_sent + loss_delay)
  return lost_packets

InCongestionRecovery(sent_time):
  return sent_time <= congestion_recovery_start_time

OnPacketsAcked(acked_packets):
  for acked_packet in acked_packets:
    OnPacketAcked(acked_packet)

OnPacketAcked(acked_packet):
  if (!acked_packet.in_flight):
    return;
  // bytes_in_flightから除外します。
  bytes_in_flight -= acked_packet.sent_bytes
  // アプリケーション制限またはフロー制御による制限の状態であれば、
  // congestion_windowを増加させません。
  if (IsAppOrFlowControlLimited())
    return
  // 回復期間中は輻輳ウィンドウを増加させません。
  if (InCongestionRecovery(acked_packet.time_sent)):
    return
  if (congestion_window < ssthresh):
    // スロースタート。
    congestion_window += acked_packet.sent_bytes
  else:
    // 輻輳回避。
    congestion_window +=
      max_datagram_size * acked_packet.sent_bytes
      / congestion_window

OnCongestionEvent(sent_time):
  // すでに回復期間中であれば何もしません。
  if (InCongestionRecovery(sent_time)):
    return

  // 回復期間に入ります。
  congestion_recovery_start_time = now()
  ssthresh = congestion_window * kLossReductionFactor
  congestion_window = max(ssthresh, kMinimumWindow)
  // 損失回復を早めるために1つのパケットを送信できます。
  MaybeSendOnePacket()

ProcessECN(ack, pn_space):
  // ピアが報告したECN-CEカウンターが増加していれば、
  // 新しい輻輳イベントである可能性があります。
  if (ack.ce_counter > ecn_ce_counters[pn_space]):
    ecn_ce_counters[pn_space] = ack.ce_counter
    sent_time = sent_packets[ack.largest_acked].time_sent
    OnCongestionEvent(sent_time)

OnPacketsLost(lost_packets):
  sent_time_of_last_loss = 0
  // 失われたパケットをbytes_in_flightから除外します。
  for lost_packet in lost_packets:
    if lost_packet.in_flight:
      bytes_in_flight -= lost_packet.sent_bytes
      sent_time_of_last_loss =
        max(sent_time_of_last_loss, lost_packet.time_sent)
  // 送信中のパケットが失われた場合は輻輳イベント
  if (sent_time_of_last_loss != 0):
    OnCongestionEvent(sent_time_of_last_loss)

  // これらのパケットの損失が持続的な輻輳を示している場合は、
  // 輻輳ウィンドウをリセットします。
  // RTTサンプルを得た後に送信されたパケットだけを考慮します。
  if (first_rtt_sample == 0):
    return
  pc_lost = []
  for lost in lost_packets:
    if lost.time_sent > first_rtt_sample:
      pc_lost.insert(lost)
  if (InPersistentCongestion(pc_lost)):
    congestion_window = kMinimumWindow
    congestion_recovery_start_time = 0
